    scattered = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                 if grid[r][c] != bg and grid[r][c] != edge_color]
    if not scattered:
        return out
    fill = scattered[0][2]

    # For top-edge bars, spread the scattered color across the full rows
    # below; for bottom bars, across rows above. Preserve edge runs.
    top = [c for c, v in enumerate(grid[0]) if v == edge_color]
    bottom = [c for c, v in enumerate(grid[-1]) if v == edge_color]
    if top:
        for r in range(1, h):
            for c in range(min(top), w):
                out[r][c] = fill
    if bottom:
        for r in range(h-1):
            for c in range(0, max(bottom)+1):
                out[r][c] = fill
